# 函数依赖集的最小覆盖(正则覆盖)计算
def closure(attrs, fds):
    res = set(attrs)
    changed = True
    while changed:
        changed = False
        for lhs, rhs in fds:
            if lhs <= res and not rhs <= res:
                res |= rhs
                changed = True
    return res


def fmt(s):
    return "".join(sorted(s)) or "-"


def dkey(fd):
    return (sorted(fd[0]), sorted(fd[1]))


def minimize(fds):
    steps = []
    # 步骤 1: 右部属性单一化
    step1 = []
    for lhs, rhs in fds:
        for a in sorted(rhs):
            step1.append((frozenset(lhs), frozenset([a])))
    step1 = sorted(set(step1), key=dkey)
    steps.append(("① 右部属性单一化", [], step1))
    # 步骤 2: 去掉冗余 FD
    cur = list(step1)
    notes2 = []
    i = 0
    while i < len(cur):
        trial = cur[:i] + cur[i + 1:]
        lhs, rhs = cur[i]
        if closure(lhs, trial) >= set(rhs):
            notes2.append("%s 冗余(由其余FD可推出) -> 删除" % ("%s->%s" % (fmt(lhs), fmt(rhs))))
            cur = trial
        else:
            i += 1
    steps.append(("② 去除冗余FD", notes2, list(cur)))
    # 步骤 3: 去掉左部冗余属性
    notes3 = []
    final = []
    for lhs, rhs in cur:
        l = set(lhs)
        for a in sorted(lhs):
            if len(l) == 1:
                break
            t = l - {a}
            if closure(frozenset(t), cur) >= set(rhs):
                notes3.append("%s->%s 中 %s 相对左部冗余 -> %s->%s"
                              % (fmt(lhs), fmt(rhs), a, fmt(t), fmt(rhs)))
                l = t
        final.append((frozenset(l), frozenset(rhs)))
    final = sorted(set(final), key=dkey)
    steps.append(("③ 左部去冗余属性", notes3, list(final)))
    return steps, final


def run_case(label, F):
    steps, final = minimize(F)
    print("[%s]" % label)
    print("  原始 F = " + ", ".join("%s->%s" % (fmt(l), fmt(r)) for l, r in F))
    for name, notes, fds in steps:
        print("  " + name + ":")
        if not fds:
            print("      (无)")
        for lhs, rhs in fds:
            print("      %s->%s" % (fmt(lhs), fmt(rhs)))
        for nt in notes:
            print("      * " + nt)
    print("  最小覆盖 = {" + ", ".join("%s->%s" % (fmt(l), fmt(r)) for l, r in final) + "}")
    allA = {"A", "B", "C"}
    same = all(closure(frozenset(x), F) == closure(frozenset(x), final)
               for x in ("A", "B", "C", "AB", "AC", "BC"))
    print("  等价性校验(逐子集闭包比对) = " + ("一致" if same else "不一致"))
    print()


print("=== 最小覆盖(正则覆盖)计算 ===")
print()
run_case("用例1 教材经典例", [
    (frozenset("A"), frozenset("BC")),
    (frozenset("B"), frozenset("C")),
    (frozenset("A"), frozenset("B")),
    (frozenset("AB"), frozenset("C")),
])
